function badRequest(status, message) {
  return { ok: false, httpStatus: status, response: { error: message } };
}

function prepareSong(prompt, instrumental, reference, generatedReference) {
  if (typeof prompt !== "string" || !prompt.trim() || prompt.trim().length > 2000) {
    throw new Error("Enter a song prompt of 1–2,000 characters.");
  }
  if (typeof instrumental !== "boolean")
    throw new Error("Choose whether the song is instrumental.");
  const hasReference = reference != null && reference !== "";
  const key = hasReference ? reference : generatedReference;
  if (
    typeof key !== "string" ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(key)
  ) {
    throw new Error("Use a random UUID v4 as your submission reference, or leave it blank.");
  }
  return {
    key: "song-form-" + key.toLowerCase(),
    body: { prompt: prompt.trim(), make_instrumental: instrumental, model: "v6" },
  };
}

function webhookSong({ body, headers }) {
  if (
    typeof headers?.["content-type"] !== "string" ||
    !/^application\/json(?:\s*;|$)/i.test(headers["content-type"])
  ) {
    return badRequest(415, "Use application/json.");
  }
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    return badRequest(400, "Send one JSON object with a song prompt.");
  }
  if ("instrumental" in body && typeof body.instrumental !== "boolean") {
    return badRequest(400, "Instrumental must be a boolean.");
  }
  const reference = headers["idempotency-key"];
  if (typeof reference !== "string" || !reference) {
    return badRequest(400, "Set Idempotency-Key to a random UUID v4.");
  }
  try {
    const song = prepareSong(body.prompt, body.instrumental ?? false, reference);
    return { ok: true, body: song.body, key: "song-webhook-" + reference.toLowerCase() };
  } catch {
    return badRequest(
      400,
      "Use a nonblank prompt of at most 2,000 characters and a UUID v4 Idempotency-Key.",
    );
  }
}

return { json: webhookSong($json) };

function badRequest(status, message) {
  return { ok: false, httpStatus: status, response: { error: message } };
}

function acceptedSongJob(reply, statusCode) {
  const jobId = reply?.job_id;
  if (statusCode !== 202 || typeof jobId !== "string" || !/^[a-zA-Z0-9_-]{1,128}$/.test(jobId)) {
    throw new Error("Tunova did not confirm a job ID. Check Tunova before submitting again.");
  }
  return { jobId, url: "https://api.tunova.ai/api/jobs/" + jobId };
}

if ($json.statusCode === 409)
  return { json: badRequest(409, "Idempotency-Key already belongs to different inputs.") };
try {
  return { json: { ok: true, ...acceptedSongJob($json.body, $json.statusCode) } };
} catch {
  return {
    json: badRequest(502, "Tunova did not confirm creation. Retry with the same key and inputs."),
  };
}

function badRequest(status, message) {
  return { ok: false, httpStatus: status, response: { error: message } };
}

function readSongJob(reply, statusCode, jobId) {
  const status = reply?.status;
  if (
    statusCode !== 200 ||
    reply?.job_id !== jobId ||
    !["queued", "processing", "submitted", "complete", "failed"].includes(status)
  ) {
    throw new Error("Tunova did not return a valid status for the submitted job.");
  }
  const result = { job_id: jobId, status, audio_url: null, title: null };
  if (status !== "complete") return result;

  const clip = Array.isArray(reply.clips) ? reply.clips[0] : undefined;
  if (
    typeof clip?.audio_url !== "string" ||
    !/^https:\/\/(?:[a-z\d](?:[a-z\d-]*[a-z\d])?\.)+[a-z]{2,}(?:[/?#][^\s\\"<>]*)?$/i.test(
      clip.audio_url,
    )
  ) {
    throw new Error("Tunova marked the job complete without a valid first audio URL.");
  }
  result.audio_url = clip.audio_url;
  result.title = typeof clip.title === "string" && clip.title.trim() ? clip.title : null;
  return result;
}

const jobId = $("Confirm the Tunova job ID").item.json.jobId;
try {
  const { status, audio_url, title } = readSongJob($json.body, $json.statusCode, jobId);
  return { json: { httpStatus: 200, response: { status, audio_url, title } } };
} catch {
  return {
    json: badRequest(
      502,
      "Tunova did not return a valid result for the job. Retry with the same key and inputs.",
    ),
  };
}
